{
  "CreatedUtc": "TIMESTAMP",
  "RequestTimeoutSeconds": 60,
  "Logging": {
    "Enable": true,
    "Servers": [
      {
        "Hostname": "127.0.0.1",
        "Port": 514
      }
    ],
    "LogDirectory": "./logs/",
    "LogFilename": "litegraph.log",
    "ConsoleLogging": true,
    "EnableColors": true,
    "JsonLogOutput": false,
    "MinimumSeverity": 0,
    "Header": "[LiteGraph] ",
    "LogQueries": false,
    "LogResults": false
  },
  "Caching": {
    "Enable": true,
    "Capacity": 1000,
    "EvictCount": 100
  },
  "Rest": {
    "Hostname": "localhost",
    "Port": 8701,
    "Prefix": "http://localhost:8701/",
    "Protocols": {
      "EnableHttp1": true,
      "EnableHttp2": false,
      "EnableHttp3": false,
      "EnableHttp2Cleartext": false,
      "MaxConcurrentStreams": 0,
      "Http2": {
        "HeaderTableSize": 4096,
        "EnablePush": false,
        "MaxConcurrentStreams": 0,
        "InitialWindowSize": 65535,
        "MaxFrameSize": 16384,
        "MaxHeaderListSize": 65536
      },
      "Http3": {
        "MaxFieldSectionSize": 0,
        "QpackMaxTableCapacity": 0,
        "QpackBlockedStreams": 0,
        "EnableDatagram": false
      },
      "IdleTimeoutMs": 0
    },
    "AltSvc": {
      "Enabled": false,
      "Port": 0,
      "Http3Alpn": "h3",
      "MaxAgeSeconds": 86400
    },
    "IO": {
      "Http1": {
        "PoolMaxRetainedPerType": 256,
        "ResponseHeaderTemplateCacheSize": 256,
