        "Access-Control-Allow-Headers": "*",
        "Access-Control-Expose-Headers": "",
        "Accept": "*/*",
        "Accept-Language": "en-US, en",
        "Accept-Charset": "ISO-8859-1, utf-8",
        "Cache-Control": "no-cache",
        "Connection": "close",
        "Host": "localhost:8000"
      }
    },
    "AccessControl": {
      "DenyList": {
        "CacheCapacity": 4096,
        "CacheCount": 0
      },
      "PermitList": {
        "CacheCapacity": 4096,
        "CacheCount": 0
      },
      "Mode": "DefaultPermit"
    },
    "Debug": {
      "AccessControl": false,
      "Routing": false,
      "Requests": false,
      "Responses": false
    },
    "Timeout": {
      "DefaultTimeout": "00:00:00"
    },
    "WebSockets": {
      "Enable": false,
