      "MaxOperations": 1000,
      "MaxTimeoutSeconds": 60
    },
    "MaxConcurrentOperations": 4,
    "InMemory": false,
    "MaxAlgorithmNodes": 1000000,
    "MaxAlgorithmEdges": 10000000
